  EXPECT_EQ(3u, PRODUCTION_ANCHORS_COUNT);
  EXPECT_EQ(1u, TEST_ANCHORS_COUNT);
  const uint8_t key_1[8] = {0xe1, 0x71, 0x6b, 0x2d, 0x48, 0x8a, 0x1c, 0x09};
