TEST(UpdChunk, Base64IsStrictAndCanonical) {
  uint8_t out[8];
  EXPECT_EQ(3, base64Decode("6Q8A", 4, out, sizeof(out)));
  EXPECT_EQ(0xE9, out[0]);
  EXPECT_EQ(0x0F, out[1]);
  EXPECT_EQ(0x00, out[2]);
  EXPECT_EQ(1, base64Decode("6Q==", 4, out, sizeof(out)));
  EXPECT_EQ(2, base64Decode("6Q8=", 4, out, sizeof(out)));
  EXPECT_EQ(6, base64Decode("+/+/+/+/", 8, out, sizeof(out)));
  EXPECT_EQ(0xFB, out[0]);
  EXPECT_EQ(0, base64Decode("", 0, out, sizeof(out)));
  // Not canonical, or not base64 at all: refused, never decoded to something.
  for (const char* bad : {"6Q", "6Q=", "6R==", "6Q9=", "6Q==6Q==", "=Q==", "6=Q=", "6Q-_", "6Q\n=", "6Q 8"})
    EXPECT_EQ(-1, base64Decode(bad, strlen(bad), out, sizeof(out))) << bad;
  EXPECT_EQ(-1, base64Decode("6Q8A6Q8A6Q8A", 12, out, 8)) << "longer than the buffer";
  EXPECT_EQ(8, base64Decode("6Q8A6Q8A6Q8=", 12, out, 8));
}

TEST(UpdChunk, StreamedHashMatchesOneShot) {
  uint8_t data[1000];
  for (size_t i = 0; i < sizeof(data); i++) data[i] = (uint8_t)(i * 7 + 3);
  uint8_t whole[32], parts[32];
  Dep::sha256(data, sizeof(data), whole);
  Dep::Sha256Ctx c;
  Dep::sha256Init(&c);
  for (size_t at = 0; at < sizeof(data); at += 63) Dep::sha256Update(&c, data + at, at + 63 <= sizeof(data) ? 63 : sizeof(data) - at);
  Dep::sha256Finish(&c, parts);
  EXPECT_EQ(0, memcmp(whole, parts, 32));
  // The empty input, as FIPS 180-4 gives it.
  static const uint8_t EMPTY[32] = {0xe3, 0xb0, 0xc4, 0x42, 0x98, 0xfc, 0x1c, 0x14, 0x9a, 0xfb, 0xf4, 0xc8, 0x99, 0x6f, 0xb9, 0x24,
                                    0x27, 0xae, 0x41, 0xe4, 0x64, 0x9b, 0x93, 0x4c, 0xa4, 0x95, 0x99, 0x1b, 0x78, 0x52, 0xb8, 0x55};
  Dep::sha256Init(&c);
  Dep::sha256Finish(&c, parts);
  EXPECT_EQ(0, memcmp(EMPTY, parts, 32));
}

TEST(UpdJob, AnOpenJobsResultChangesATerminalOneNever) {
  Iface::JobTable t;
  Iface::Job* j = t.open("u1", "update.offer");
  ASSERT_NE(nullptr, j);
  ASSERT_TRUE(t.awaitConfirm(j, 300, false, Iface::BOOT_ABNORMAL));
  const char att[] = "{\"update\":{\"job\":\"u1\"}}";
  EXPECT_TRUE(t.setResult(j, att, sizeof(att) - 1));
  EXPECT_EQ(Iface::JOB_AWAITING, j->state);
  EXPECT_EQ(std::string(att), std::string(j->result, j->result_len));
  ASSERT_TRUE(t.setState(j, Iface::JOB_CONFIRMED));
  EXPECT_FALSE(t.setResult(j, "{\"x\":1}", 7));
  EXPECT_EQ(std::string(att), std::string(j->result, j->result_len));
}

// ---- update.manifest.part (docs/contract/LORA_UPDATES.md section 5)

namespace {

std::string b64(const uint8_t* p, size_t n) {
  static const char A[] = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
  std::string o;
  for (size_t i = 0; i < n; i += 3) {
    const uint32_t g = (uint32_t)p[i] << 16 | (i + 1 < n ? (uint32_t)p[i + 1] << 8 : 0) | (i + 2 < n ? p[i + 2] : 0);
    o += A[g >> 18 & 63];
    o += A[g >> 12 & 63];
    o += i + 1 < n ? A[g >> 6 & 63] : '=';
    o += i + 2 < n ? A[g & 63] : '=';
  }
  return o;
}

std::vector<uint8_t> blobOf(size_t n, uint8_t seed) {
  std::vector<uint8_t> v(n);
  for (size_t i = 0; i < n; i++) v[i] = (uint8_t)(seed + i * 7);
  return v;
}

struct Sha { uint8_t h[32]; explicit Sha(uint8_t b) { memset(h, b, 32); } };

// Part `part` (1-based) of `parts`, cut evenly from blob.
ManifestParts::Verdict addPart(ManifestParts& mp, const Sha& sha, const std::vector<uint8_t>& blob, unsigned part, unsigned parts) {
  const size_t each = (blob.size() + parts - 1) / parts;
  const size_t from = (part - 1) * each, to = std::min(blob.size(), from + each);
  const std::string t = b64(blob.data() + from, to - from);
  return mp.add(sha.h, part, parts, t.c_str(), t.size());
}

}  // namespace

TEST(UpdManifestParts, PartsInOrderJoinIntoTheWhole) {
  ManifestParts mp;
  const Sha sha(1);
  const auto blob = blobOf(300, 5);
  EXPECT_EQ(ManifestParts::MP_MORE, addPart(mp, sha, blob, 1, 3));
  EXPECT_EQ(1u, mp.held());
  EXPECT_EQ(ManifestParts::MP_MORE, addPart(mp, sha, blob, 2, 3));
  EXPECT_EQ(ManifestParts::MP_COMPLETE, addPart(mp, sha, blob, 3, 3));
  uint8_t out[ManifestParts::TOTAL_MAX];
  ASSERT_EQ(blob.size(), mp.join(out, sizeof(out)));
  EXPECT_EQ(0, memcmp(out, blob.data(), blob.size()));
}

TEST(UpdManifestParts, PartsOutOfOrderJoinInTheOrderOfTheirNumbers) {
  ManifestParts mp;
  const Sha sha(1);
  const auto blob = blobOf(704, 9);   // the longest: a 640-byte text and its 64-byte signature, in four full parts
  EXPECT_EQ(ManifestParts::MP_MORE, addPart(mp, sha, blob, 4, 4));
  EXPECT_EQ(ManifestParts::MP_MORE, addPart(mp, sha, blob, 2, 4));
  EXPECT_EQ(ManifestParts::MP_MORE, addPart(mp, sha, blob, 3, 4));
  EXPECT_EQ(0u, mp.join(nullptr, 0)) << "nothing is joined until every part is held";
  EXPECT_EQ(ManifestParts::MP_COMPLETE, addPart(mp, sha, blob, 1, 4));
  uint8_t out[ManifestParts::TOTAL_MAX];
  ASSERT_EQ(blob.size(), mp.join(out, sizeof(out)));
  EXPECT_EQ(0, memcmp(out, blob.data(), blob.size()));
}

TEST(UpdManifestParts, APartHeldTwiceIsReplacedNotCounted) {
  ManifestParts mp;
  const Sha sha(1);
  const auto a = blobOf(200, 1), b = blobOf(200, 2);
  EXPECT_EQ(ManifestParts::MP_MORE, addPart(mp, sha, a, 1, 2));
  EXPECT_EQ(ManifestParts::MP_MORE, addPart(mp, sha, a, 1, 2));
  EXPECT_EQ(1u, mp.held());
  EXPECT_EQ(ManifestParts::MP_COMPLETE, addPart(mp, sha, b, 2, 2));
}

TEST(UpdManifestParts, APartForAnotherHashDiscardsWhatWasHeld) {
  ManifestParts mp;
  const Sha x(1), y(2);
  const auto bx = blobOf(300, 1), by = blobOf(300, 2);
  EXPECT_EQ(ManifestParts::MP_MORE, addPart(mp, x, bx, 1, 2));
  EXPECT_EQ(ManifestParts::MP_MORE, addPart(mp, y, by, 2, 2)) << "y's second part is not x's first completed";
  EXPECT_EQ(1u, mp.held());
  EXPECT_EQ(0, memcmp(mp.sha(), y.h, 32)) << "the slot is y's now";
  EXPECT_EQ(ManifestParts::MP_MORE, addPart(mp, x, bx, 2, 2)) << "and x's second part finds x's first gone";
  EXPECT_EQ(0, memcmp(mp.sha(), x.h, 32));
  EXPECT_EQ(ManifestParts::MP_COMPLETE, addPart(mp, x, bx, 1, 2));
  uint8_t out[ManifestParts::TOTAL_MAX];
  ASSERT_EQ(bx.size(), mp.join(out, sizeof(out)));
  EXPECT_EQ(0, memcmp(out, bx.data(), bx.size())) << "only x's own bytes";
}

TEST(UpdManifestParts, AChangedPartCountDiscardsWhatWasHeld) {
  ManifestParts mp;
  const Sha sha(1);
  const auto blob = blobOf(300, 1);
  EXPECT_EQ(ManifestParts::MP_MORE, addPart(mp, sha, blob, 1, 3));
  EXPECT_EQ(ManifestParts::MP_MORE, addPart(mp, sha, blob, 2, 2)) << "cut another way: the old parts do not count";
  EXPECT_EQ(1u, mp.held());
  EXPECT_EQ(2u, mp.parts());
}

TEST(UpdManifestParts, MoreThanFourPartsAndBadPartsAreRefusedAndKeepNothing) {
  ManifestParts mp;
  const Sha sha(1);
  const auto blob = blobOf(100, 1);
  const std::string ok = b64(blob.data(), 50);
  EXPECT_EQ(ManifestParts::MP_BAD, mp.add(sha.h, 1, 5, ok.c_str(), ok.size()));
  EXPECT_EQ(ManifestParts::MP_BAD, mp.add(sha.h, 5, 5, ok.c_str(), ok.size()));
  EXPECT_EQ(ManifestParts::MP_BAD, mp.add(sha.h, 0, 2, ok.c_str(), ok.size())) << "parts count from 1";
  EXPECT_EQ(ManifestParts::MP_BAD, mp.add(sha.h, 3, 2, ok.c_str(), ok.size()));
  EXPECT_EQ(ManifestParts::MP_BAD, mp.add(sha.h, 1, 0, ok.c_str(), ok.size()));
  EXPECT_FALSE(mp.open());
  const auto big = blobOf(ManifestParts::PART_MAX + 1, 1);
  const std::string over = b64(big.data(), big.size());
  EXPECT_EQ(ManifestParts::MP_BAD, mp.add(sha.h, 1, 4, over.c_str(), over.size())) << "one part is at most 176 bytes";
  EXPECT_EQ(ManifestParts::MP_BAD, mp.add(sha.h, 1, 2, "", 0));
  EXPECT_EQ(ManifestParts::MP_MORE, mp.add(sha.h, 1, 4, ok.c_str(), ok.size())) << "the same part is fine with 4 parts";
  // A refused part leaves what was held alone.
  EXPECT_EQ(ManifestParts::MP_BAD, mp.add(sha.h, 2, 5, ok.c_str(), ok.size()));
  EXPECT_EQ(1u, mp.held());
}

TEST(UpdManifestParts, OnlyCanonicalBase64IsTaken) {
  ManifestParts mp;
  const Sha sha(1);
  EXPECT_EQ(ManifestParts::MP_BAD, mp.add(sha.h, 1, 2, "QUJD=", 5)) << "length";
  EXPECT_EQ(ManifestParts::MP_BAD, mp.add(sha.h, 1, 2, "QUJ=", 4)) << "leftover bits set";
  EXPECT_EQ(ManifestParts::MP_BAD, mp.add(sha.h, 1, 2, "QU==", 4)) << "leftover bits set";
  EXPECT_EQ(ManifestParts::MP_BAD, mp.add(sha.h, 1, 2, "QU-_", 4)) << "the URL alphabet";
  EXPECT_EQ(ManifestParts::MP_BAD, mp.add(sha.h, 1, 2, "QUJD\n", 5));
  EXPECT_FALSE(mp.open());
  EXPECT_EQ(ManifestParts::MP_MORE, mp.add(sha.h, 1, 2, "QUJD", 4));
}

// ---- update.offer, source.lora (docs/contract/LORA_UPDATES.md section 4)

namespace {

const uint32_t ISSUED = 1792800000;

// The offer as a request object: issued_at at its top level (`top`, "" for none) beside `op` and `args`, and in the args
// (`in_args`, "" for none), with source.lora spelt as given. `is_signed` as the request's authority says.
Upd::LoraSourceVerdict lora(const std::string& lora_obj, const std::string& top, bool clock_known = false, uint32_t clock = 0,
                            Upd::LoraSource* out = nullptr, const std::string& in_args = "", bool is_signed = false) {
  const std::string req = "{\"v\":1,\"id\":\"o\",\"op\":\"update.offer\"," + (top.empty() ? "" : "\"issued_at\":" + top + ",") +
                          "\"args\":{\"manifest_sha256\":\"00\"," + (in_args.empty() ? "" : "\"issued_at\":" + in_args + ",") +
                          "\"source\":{\"lora\":" + lora_obj + "}}}";
  Iface::JsonBuf<Iface::MAX_TOKENS> doc;
  EXPECT_EQ(Iface::J_OK, Iface::jsonParse(doc, req.c_str(), req.size())) << req;
  const int args = Iface::jsonFind(doc, 0, "args");
  uint32_t issued;
  if (!Upd::readIssuedAt(doc, args, is_signed, &issued)) return Upd::LS_BAD_ARGS;
  const int src = Iface::jsonFind(doc, args, "source");
  Upd::LoraSource tmp;
  return Upd::readLoraSource(doc, issued, Iface::jsonFind(doc, src, "lora"), clock_known, clock, out ? out : &tmp);
}

std::string at(uint32_t t) { return std::to_string(t); }

}  // namespace

TEST(UpdLoraOffer, AWellFormedSourceIsRead) {
  Upd::LoraSource s = {};
  EXPECT_EQ(Upd::LS_OK, lora("{\"block\":8,\"window_end\":" + at(ISSUED + 3600) + "}", at(ISSUED), false, 0, &s));
  EXPECT_EQ(8u, s.block);
  EXPECT_EQ(ISSUED + 3600, s.window_end);
  EXPECT_EQ(ISSUED, s.issued_at);
  EXPECT_EQ(Upd::LS_OK, lora("{\"window_end\":" + at(ISSUED + 60) + ",\"block\":1}", at(ISSUED)));
}

TEST(UpdLoraOffer, IssuedAtComesFromTheSignedBodyAndTheArgsOnlyServeAnUnsignedRequest) {
  const std::string src = "{\"block\":8,\"window_end\":" + at(ISSUED + 600) + "}";
  Upd::LoraSource s = {};
  EXPECT_EQ(Upd::LS_OK, lora(src, at(ISSUED), false, 0, &s, "", true));
  EXPECT_EQ(ISSUED, s.issued_at) << "a signed request's own, at the top level";
  EXPECT_EQ(Upd::LS_BAD_ARGS, lora(src, "", false, 0, nullptr, at(ISSUED), true)) << "a signed request has one at the top";
  EXPECT_EQ(Upd::LS_BAD_ARGS, lora(src, at(ISSUED), false, 0, nullptr, at(ISSUED + 1), true)) << "args that differ from the body";
  EXPECT_EQ(Upd::LS_BAD_ARGS, lora(src, at(ISSUED), false, 0, nullptr, at(ISSUED + 1), false)) << "unsigned too, when both are given";
  EXPECT_EQ(Upd::LS_OK, lora(src, at(ISSUED), false, 0, &s, at(ISSUED), true)) << "the same in both is fine";
  EXPECT_EQ(Upd::LS_OK, lora(src, "", false, 0, &s, at(ISSUED), false)) << "unsigned, args only";
  EXPECT_EQ(ISSUED, s.issued_at);
  EXPECT_EQ(Upd::LS_BAD_ARGS, lora(src, "", false, 0, nullptr, "", false)) << "none at all";
  EXPECT_EQ(Upd::LS_BAD_ARGS, lora(src, "\"x\"", false, 0, nullptr, "", true));
  // The window is measured from the top-level one: here the args' would have made it 12 hours and a minute.
  const std::string long_window = "{\"block\":8,\"window_end\":" + at(ISSUED + 12 * 3600 + 60) + "}";
  EXPECT_EQ(Upd::LS_BAD_ARGS, lora(long_window, at(ISSUED), false, 0, nullptr, "", true));
  EXPECT_EQ(Upd::LS_OK, lora(long_window, at(ISSUED + 60), false, 0, nullptr, "", true));
}

TEST(UpdLoraOffer, TheBlockIsOneToEight) {
  const std::string w = ",\"window_end\":" + at(ISSUED + 600) + "}";
  for (const char* b : {"0", "9", "-1", "\"8\"", "8.5", "null", "true"})
    EXPECT_EQ(Upd::LS_BAD_ARGS, lora(std::string("{\"block\":") + b + w, at(ISSUED))) << b;
  EXPECT_EQ(Upd::LS_BAD_ARGS, lora("{\"window_end\":" + at(ISSUED + 600) + "}", at(ISSUED))) << "required";
  for (int b = 1; b <= 8; b++) EXPECT_EQ(Upd::LS_OK, lora("{\"block\":" + std::to_string(b) + w, at(ISSUED))) << b;
}

TEST(UpdLoraOffer, TheWindowIsRequiredAfterIssuedAndAtMostTwelveHours) {
  auto offer = [&](uint32_t we, const std::string& issued = at(ISSUED)) {
    return lora("{\"block\":8,\"window_end\":" + at(we) + "}", issued);
  };
  EXPECT_EQ(Upd::LS_OK, offer(ISSUED + 12 * 3600)) << "exactly 12 hours";
  EXPECT_EQ(Upd::LS_BAD_ARGS, offer(ISSUED + 12 * 3600 + 1)) << "a second more";
  EXPECT_EQ(Upd::LS_BAD_ARGS, offer(ISSUED + 24 * 3600));
  EXPECT_EQ(Upd::LS_BAD_ARGS, offer(ISSUED)) << "not after it was issued";
  EXPECT_EQ(Upd::LS_BAD_ARGS, offer(ISSUED - 5));
  EXPECT_EQ(Upd::LS_OK, offer(ISSUED + 1));
  EXPECT_EQ(Upd::LS_BAD_ARGS, lora("{\"block\":8}", at(ISSUED))) << "window_end is required";
  EXPECT_EQ(Upd::LS_BAD_ARGS, lora("{\"block\":8,\"window_end\":\"soon\"}", at(ISSUED)));
  EXPECT_EQ(Upd::LS_BAD_ARGS, lora("{\"block\":8,\"window_end\":" + at(ISSUED + 60) + "}", "")) << "issued_at is required";
  EXPECT_EQ(Upd::LS_BAD_ARGS, lora("{\"block\":8,\"window_end\":" + at(ISSUED + 60) + "}", "0"));
}

TEST(UpdLoraOffer, AWindowTheDevicesClockSaysIsOverIsPast) {
  const std::string src = "{\"block\":8,\"window_end\":" + at(ISSUED + 600) + "}";
  EXPECT_EQ(Upd::LS_OK, lora(src, at(ISSUED), true, ISSUED + 599));
  EXPECT_EQ(Upd::LS_BAD_ARGS, lora(src, at(ISSUED), true, ISSUED + 600));
  EXPECT_EQ(Upd::LS_BAD_ARGS, lora(src, at(ISSUED), true, ISSUED + 5000));
  EXPECT_EQ(Upd::LS_OK, lora(src, at(ISSUED), false, ISSUED + 5000)) << "an unset clock says nothing";
}

TEST(UpdLoraOffer, APresetIsUnsupportedHereAfterTheRestIsChecked) {
  const std::string w = "\"block\":8,\"window_end\":" + at(ISSUED + 600);
  EXPECT_EQ(Upd::LS_UNSUPPORTED, lora("{" + w + ",\"preset\":\"fast\"}", at(ISSUED)));
  EXPECT_EQ(Upd::LS_UNSUPPORTED, lora("{" + w + ",\"preset\":\"slow\"}", at(ISSUED))) << "any preset, in this slice";
  EXPECT_EQ(Upd::LS_BAD_ARGS, lora("{\"block\":9,\"window_end\":" + at(ISSUED + 600) + ",\"preset\":\"fast\"}", at(ISSUED)))
      << "a malformed source is malformed before it is unsupported";
}

TEST(UpdLoraOffer, AMalformedSourceIsBadArgs) {
  EXPECT_EQ(Upd::LS_BAD_ARGS, lora("[]", at(ISSUED)));
  EXPECT_EQ(Upd::LS_BAD_ARGS, lora("true", at(ISSUED)));
  EXPECT_EQ(Upd::LS_BAD_ARGS, lora("{}", at(ISSUED)));
  EXPECT_EQ(Upd::LS_BAD_ARGS, lora("{\"block\":8,\"window_end\":" + at(ISSUED + 60) + ",\"extra\":1}", at(ISSUED)));
}

TEST(UpdSlotResume, TheSectorHoldingTheOffsetIsNeverErasedAndOneStartingAtItIs) {
  const uint32_t S = 4096;
  EXPECT_EQ(0u, slotFirstErase(0, S)) << "nothing written: the first sector is erased as the write reaches it";
  EXPECT_EQ(S, slotFirstErase(1, S)) << "an offset inside sector 0 keeps sector 0";
  EXPECT_EQ(S, slotFirstErase(115, S));
  EXPECT_EQ(S, slotFirstErase(S - 1, S));
  EXPECT_EQ(S, slotFirstErase(S, S)) << "an offset at the start of sector 1 holds none of it: erased when reached";
  EXPECT_EQ(3 * S, slotFirstErase(72 * 115, S)) << "8,280 bytes lie in sector 2";
  for (uint32_t off : {1u, 100u, 4095u, 4096u, 4097u, 8280u, 1000000u}) {
    const uint32_t first = slotFirstErase(off, S);
    EXPECT_GE(first, off) << off << ": never below the offset, so the sector holding it is kept";
    EXPECT_LT(first - off, S) << off;
    EXPECT_EQ(0u, first % S) << off;
  }
}

TEST(UpdManifest, ACompressedImageIsNotAManifestThisVersionReads) {
  // image.encoding (a deflate transfer, LORA_UPDATES.md section 6) is a later slice; a version 1 manifest with an unknown key is
  // refused at staging, so a deflate manifest is never offered over LoRa or any other way here.
  std::string text = UPD_VALID.manifest;
  const size_t at = text.find("\"image\":{");
  ASSERT_NE(std::string::npos, at);
  text.insert(at + 9, "\"encoding\":\"deflate\",");
  Manifest m;
  EXPECT_FALSE(parseManifest(text.c_str(), text.size(), &m));
}

TEST(UpdUrl, AUrlIsReadStrictly) {
  Url u;
  ASSERT_TRUE(parseUrl("https://mecon.cloud/fw/abc.bin?x=1", &u));
  EXPECT_TRUE(u.tls);
  EXPECT_STREQ("mecon.cloud", u.host);
  EXPECT_EQ(443, u.port);
  EXPECT_STREQ("/fw/abc.bin?x=1", u.path);
  ASSERT_TRUE(parseUrl("http://10.0.0.69:8080", &u));
  EXPECT_FALSE(u.tls);
  EXPECT_EQ(8080, u.port);
  EXPECT_STREQ("/", u.path);
  uint32_t a = 0;
  EXPECT_TRUE(urlIpv4(u.host, &a));
  EXPECT_EQ(0x0A000045u, a);
  EXPECT_FALSE(urlIpv4("mecon.cloud", &a));
  EXPECT_FALSE(urlIpv4("10.0.0.256", &a));
  EXPECT_FALSE(urlIpv4("10.0.0", &a));
  for (const char* bad : {"ftp://h/x", "https://", "https://user@h/x", "https://h:0/x", "https://h:65536/x", "https://h:/x",
                          "https://[::1]/x", "https://h/a b", "https://h/a#frag", "https://h/\x7f", "https://h_x/a", "HTTPS://h/x"})
    EXPECT_FALSE(parseUrl(bad, &u)) << bad;
  std::string longhost = "https://" + std::string(64, 'a') + "/x";
  EXPECT_FALSE(parseUrl(longhost.c_str(), &u)) << "a host of 64 characters";
  std::string longpath = "https://h/" + std::string(199, 'a');
  EXPECT_FALSE(parseUrl(longpath.c_str(), &u)) << "a path of 200 characters";
}

TEST(UpdUrl, TheResponseHeadGivesStatusLengthAndEncoding) {
  HttpHead h;
  httpHeadLine(h, "HTTP/1.1 200 OK");
  httpHeadLine(h, "Content-Type: application/octet-stream");
  httpHeadLine(h, "CONTENT-LENGTH:  1767376 ");
  EXPECT_EQ(200, h.status);
  EXPECT_TRUE(h.has_length);
  EXPECT_EQ(1767376u, h.length);
  EXPECT_FALSE(h.chunked);
  EXPECT_FALSE(h.bad);
  HttpHead c;
  httpHeadLine(c, "HTTP/1.0 404 Not Found");
  httpHeadLine(c, "Transfer-Encoding: chunked");
  EXPECT_EQ(404, c.status);
  EXPECT_TRUE(c.chunked);
  HttpHead two;   // two lengths that disagree: refused, not the first or the last
  httpHeadLine(two, "HTTP/1.1 200 OK");
  httpHeadLine(two, "Content-Length: 10");
  httpHeadLine(two, "Content-Length: 11");
  EXPECT_TRUE(two.bad);
  for (const char* bad : {"HTTP/2 200 OK", "HTTP/1.1 20 OK", "HTTP/1.1 600 X", "HTTP/1.1 2000 X", "ICY 200 OK"}) {
    HttpHead b;
    httpHeadLine(b, bad);
    EXPECT_TRUE(b.bad) << bad;
  }
  HttpHead n;
  httpHeadLine(n, "HTTP/1.1 200 OK");
  httpHeadLine(n, "Content-Length: 12a");
  EXPECT_TRUE(n.bad);
}

